// The OS graph core (rust/os-graph) running as WebAssembly inside the page.
//
// The page is a file:// document in a macOS WKWebView, loaded as one classic script, so it
// cannot fetch a .wasm file. The bytes are embedded (bytes.ts, generated by
// scripts/build-os-wasm.sh) and instantiated synchronously on first use. The glue in pkg/ is
// the wasm-bindgen output for --target web with no default module path, so it has no
// import.meta.url and needs no bundler asset handling.
//
// The core speaks JSON. These wrappers serialise the inputs, parse the output and turn the
// `{ "error": ... }` object the core returns on bad input into a thrown Error.
import { initSync, build_system_graph_json, orbit_layout_json } from './pkg/graph_kit_os.js';
import { OS_GRAPH_WASM_BASE64 } from './bytes';
import type { CGData } from '../../../typescript/src/models';
import type {
  BuildOptions,
  OrbitLayout,
  OrbitOptions,
  OsSnapshot,
  SystemGraph,
  Vec3,
} from '../../../typescript/src/system/types';

type Base64Decoder = { from(data: string, encoding: 'base64'): Uint8Array };

/** Bytes of the embedded module. `atob` is used in the page; `Buffer` covers node (tests). */
function decodeBase64(b64: string): Uint8Array {
  if (typeof atob === 'function') {
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }
  const buffer = (globalThis as { Buffer?: Base64Decoder }).Buffer;
  if (!buffer) throw new Error('OS graph core: no base64 decoder (atob or Buffer) is available');
  return buffer.from(b64, 'base64');
}

let ready = false;

/**
 * Instantiates the core on first call (synchronously). Later calls are no-ops. The wrappers
 * below call this themselves; it is exported so a host can pay the cost up front.
 */
export function initOsGraph(): void {
  if (ready) return;
  initSync({ module: decodeBase64(OS_GRAPH_WASM_BASE64) });
  ready = true;
}

/** Parses a core response and throws when it is the `{ error }` object. */
function parseResult(json: string, what: string): unknown {
  const value = JSON.parse(json) as unknown;
  if (value !== null && typeof value === 'object' && 'error' in value) {
    throw new Error(`${what}: ${String((value as { error: unknown }).error)}`);
  }
  return value;
}

/** The system graph for a snapshot and/or a project (either may be null). */
export function buildSystemGraph(
  snapshot: OsSnapshot | null,
  project: CGData | null,
  opts: BuildOptions = {},
): SystemGraph {
  initOsGraph();
  const json = build_system_graph_json(
    JSON.stringify(snapshot ?? null),
    JSON.stringify(project ?? null),
    JSON.stringify(opts ?? null),
  );
  return parseResult(json, 'buildSystemGraph') as SystemGraph;
}

type WireLayout = {
  core: [string, Vec3][];
  ring: [string, Vec3][];
  communityCenters: Vec3[];
  bounds: { radius: number };
};

/** The 3D layout of a system graph. Maps are keyed by id, in the order the core gives them. */
export function orbitLayout(graph: SystemGraph, opts: OrbitOptions = {}): OrbitLayout {
  initOsGraph();
  const json = orbit_layout_json(JSON.stringify(graph), JSON.stringify(opts ?? null));
  const wire = parseResult(json, 'orbitLayout') as WireLayout;
  return {
    core: new Map(wire.core),
    ring: new Map(wire.ring),
    communityCenters: wire.communityCenters,
    bounds: wire.bounds,
  };
}
